//! Integration of the imported standalone local-administration component.
use sha2::{Digest, Sha256};
use std::{fs, path::Path, process::Command};

const HEADER: &str = r###"#!/bin/bash
# DMITBox local safety refactor. Generated by build/build.py; edit src/ instead.
set -u -o pipefail
IFS=$' \t\n'
umask 077
PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
unset BASH_ENV ENV CDPATH GLOBIGNORE
LC_ALL=C
export LC_ALL
readonly DMB_VERSION='4.0.0-dev'
DMB_STATE_DIR=/var/lib/dmitbox-local
DMB_CONFIG_DIR=/etc/dmitbox-local
DMB_RUNTIME_DIR=/run/dmitbox-local
DMB_LOCK_DIR=/run/dmitbox-local/locks
DMB_ETC_ROOT=/etc
DMB_RUN_ROOT=/run
DMB_ARTIFACT=$(readlink -f -- "${BASH_SOURCE[0]}") || exit 78
readonly DMB_STATE_DIR DMB_CONFIG_DIR DMB_RUNTIME_DIR DMB_LOCK_DIR DMB_ETC_ROOT DMB_RUN_ROOT DMB_ARTIFACT
declare -a DMB_LOCK_FDS=()
"###;
const MODULES: &[&str] = &[
    "core.sh",
    "validation.sh",
    "filesystem.sh",
    "gai.sh",
    "confirmation.sh",
    "adapters/dns.sh",
    "adapters/routing.sh",
    "adapters/ipv6.sh",
    "adapters/pool.sh",
    "adapters/nft.sh",
    "adapters/nat66.sh",
    "adapters/ssh.sh",
    "adapters/runtime.sh",
    "transaction.sh",
    "recovery/supervisor.sh",
    "main.sh",
];

pub fn run(root: &Path, args: &[String]) -> Result<(), String> {
    let action = args.first().map(String::as_str).unwrap_or("build");
    if args.len() > 1 || !matches!(action, "build" | "check") {
        return Err("usage: cargo xtask local-tool [build|check]".into());
    }
    let component = root.join("tools/dmitbox-local");
    let mut output = HEADER.to_owned();
    for name in MODULES {
        let data =
            fs::read_to_string(component.join("src").join(name)).map_err(|e| e.to_string())?;
        let data = if data.starts_with("#!") {
            data.split_once('\n').map(|(_, rest)| rest).unwrap_or("")
        } else {
            &data
        };
        output.push_str(&format!(
            "\n# BEGIN MODULE {name}\n{}\n# END MODULE {name}\n",
            data.trim_end()
        ));
    }
    output.push_str("\ndmb_main \"$@\"\n");
    let dist = component.join("dist");
    fs::create_dir_all(&dist).map_err(|e| e.to_string())?;
    fs::write(dist.join("dmitbox-local.sh"), output.as_bytes()).map_err(|e| e.to_string())?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(
            dist.join("dmitbox-local.sh"),
            fs::Permissions::from_mode(0o700),
        )
        .map_err(|e| e.to_string())?;
    }
    let hash = format!("{:x}", Sha256::digest(output.as_bytes()));
    fs::write(
        dist.join("SHA256SUMS"),
        format!("{hash}  dmitbox-local.sh\n"),
    )
    .map_err(|e| e.to_string())?;
    let status = Command::new("bash")
        .arg("-n")
        .arg(dist.join("dmitbox-local.sh"))
        .status()
        .map_err(|e| e.to_string())?;
    if !status.success() {
        return Err("local tool Bash syntax failed".into());
    }
    println!(
        "Local tool: {} (SHA256 {hash})",
        dist.join("dmitbox-local.sh").display()
    );
    if action == "check" {
        let status = Command::new("bash")
            .arg("tests/run.sh")
            .current_dir(&component)
            .status()
            .map_err(|e| e.to_string())?;
        if !status.success() {
            return Err("local tool checks failed; inspect its artifacts/ report".into());
        }
    }
    Ok(())
}
